#include <bits/stdc++.h>
using namespace std;

class Salary;

class Visitor {
public:
    virtual void visit(Salary& salary) = 0;
    virtual ~Visitor() = default;
};

class Salary {
public:
    // Objects stay simple - they just accept visitors
    void accept(Visitor& visitor) {
        visitor.visit(*this);
    }
};

class TaxVisitorDemo : public Visitor {
public:
    void visit(Salary& salary) override {
        cout << "Calculating tax..." << endl;
    }
};

class AuditVisitorDemo : public Visitor {
public:
    void visit(Salary& salary) override {
        cout << "Auditing..." << endl;
    }
};

class ReportVisitorDemo : public Visitor {
public:
    void visit(Salary& salary) override {
        cout << "Generating report..." << endl;
    }
};

int main() {
    Salary salary;
    TaxVisitorDemo taxVisitor;
    AuditVisitorDemo auditVisitor;
    ReportVisitorDemo reportVisitor;

    // Objects stay simple - they just accept visitors
    salary.accept(taxVisitor);
    salary.accept(auditVisitor);
    salary.accept(reportVisitor);
    return 0;
}

