interface CartItem {
    double calculateTax();
    double applyDiscount(double percent);
    String generateInvoiceLine();
    String estimateDelivery();
}

class PhysicalItem implements CartItem {
    private String name;
    private double price;

    public PhysicalItem(String name, double price) {
        this.name  = name;
        this.price = price;
    }

    public double calculateTax()                  { return price * 0.18; }
    public double applyDiscount(double percent)   { return price - (price * percent / 100); }
    public String generateInvoiceLine()           { return name + " (Physical): $" + price; }
    public String estimateDelivery()              { return "3-5 business days"; }
}

class DigitalItem implements CartItem {
    private String name;
    private double price;

    public DigitalItem(String name, double price) {
        this.name  = name;
        this.price = price;
    }

    public double calculateTax()                  { return price * 0.12; }
    public double applyDiscount(double percent)   { return price - (price * percent / 100); }
    public String generateInvoiceLine()           { return name + " (Digital): $" + price; }
    public String estimateDelivery()              { return "Instant download"; }
}

class SubscriptionItem implements CartItem {
    private String name;
    private double monthlyPrice;

    public SubscriptionItem(String name, double monthlyPrice) {
        this.name         = name;
        this.monthlyPrice = monthlyPrice;
    }

    public double calculateTax()                  { return monthlyPrice * 0.05; }
    public double applyDiscount(double percent)   { return monthlyPrice - (monthlyPrice * percent / 100); }
    public String generateInvoiceLine()           { return name + " (Subscription): $" + monthlyPrice + "/mo"; }
    public String estimateDelivery()              { return "Activated immediately"; }
}

