from abc import ABC, abstractmethod


class CartItem(ABC):
    @abstractmethod
    def calculate_tax(self):
        pass

    @abstractmethod
    def apply_discount(self, percent):
        pass

    @abstractmethod
    def generate_invoice_line(self):
        pass

    @abstractmethod
    def estimate_delivery(self):
        pass


class PhysicalItem(CartItem):
    def __init__(self, name, price):
        self.name = name
        self.price = price

    def calculate_tax(self):
        return self.price * 0.18

    def apply_discount(self, percent):
        return self.price - (self.price * percent / 100)

    def generate_invoice_line(self):
        return f"{self.name} (Physical): ${self.price}"

    def estimate_delivery(self):
        return "3-5 business days"


class DigitalItem(CartItem):
    def __init__(self, name, price):
        self.name = name
        self.price = price

    def calculate_tax(self):
        return self.price * 0.12

    def apply_discount(self, percent):
        return self.price - (self.price * percent / 100)

    def generate_invoice_line(self):
        return f"{self.name} (Digital): ${self.price}"

    def estimate_delivery(self):
        return "Instant download"


class SubscriptionItem(CartItem):
    def __init__(self, name, monthly_price):
        self.name = name
        self.monthly_price = monthly_price

    def calculate_tax(self):
        return self.monthly_price * 0.05

    def apply_discount(self, percent):
        return self.monthly_price - (self.monthly_price * percent / 100)

    def generate_invoice_line(self):
        return f"{self.name} (Subscription): ${self.monthly_price}/mo"

    def estimate_delivery(self):
        return "Activated immediately"


if __name__ == "__main__":
    item = PhysicalItem("Mechanical Keyboard", 120.00)
    print(item.generate_invoice_line())
    print(f"Tax: ${item.calculate_tax()}")

