#include <bits/stdc++.h>
using namespace std;

class CartItem {
public:
    virtual double calculateTax() = 0;
    virtual double applyDiscount(double percent) = 0;
    virtual string generateInvoiceLine() = 0;
    virtual string estimateDelivery() = 0;
    virtual ~CartItem() = default;
};

class PhysicalItem : public CartItem {
    string name;
    double price;
public:
    PhysicalItem(string name, double price) : name(name), price(price) {}

    double calculateTax() override { return price * 0.18; }
    double applyDiscount(double percent) override { return price - (price * percent / 100); }
    string generateInvoiceLine() override { return name + " (Physical): $" + to_string(price); }
    string estimateDelivery() override { return "3-5 business days"; }
};

class DigitalItem : public CartItem {
    string name;
    double price;
public:
    DigitalItem(string name, double price) : name(name), price(price) {}

    double calculateTax() override { return price * 0.12; }
    double applyDiscount(double percent) override { return price - (price * percent / 100); }
    string generateInvoiceLine() override { return name + " (Digital): $" + to_string(price); }
    string estimateDelivery() override { return "Instant download"; }
};

class SubscriptionItem : public CartItem {
    string name;
    double monthlyPrice;
public:
    SubscriptionItem(string name, double monthlyPrice) : name(name), monthlyPrice(monthlyPrice) {}

    double calculateTax() override { return monthlyPrice * 0.05; }
    double applyDiscount(double percent) override { return monthlyPrice - (monthlyPrice * percent / 100); }
    string generateInvoiceLine() override { return name + " (Subscription): $" + to_string(monthlyPrice) + "/mo"; }
    string estimateDelivery() override { return "Activated immediately"; }
};

int main() {
    PhysicalItem item("Mechanical Keyboard", 120.00);
    cout << item.generateInvoiceLine() << endl;
    cout << "Tax: $" << item.calculateTax() << endl;
    return 0;
}

