    def get_price(self):
        pass


class PhysicalItem(CartItem):
    def __init__(self, name, price):
        self.name = name
        self.price = price

    def get_name(self):
        return self.name

    def get_price(self):
        return self.price

    def accept(self, visitor):
        visitor.visit_physical(self)


class DigitalItem(CartItem):
    def __init__(self, name, price):
        self.name = name
        self.price = price

    def get_name(self):
        return self.name

    def get_price(self):
        return self.price

    def accept(self, visitor):
        visitor.visit_digital(self)


class SubscriptionItem(CartItem):
    def __init__(self, name, monthly_price):
        self.name = name
        self.monthly_price = monthly_price

    def get_name(self):
        return self.name

    def get_price(self):
        return self.monthly_price

    def accept(self, visitor):
        visitor.visit_subscription(self)


class TaxVisitor(ItemVisitor):
    def visit_physical(self, item):
        tax = item.get_price() * 0.18
        print(f"Tax [Physical] {item.get_name()}: ${tax}")

    def visit_digital(self, item):
        tax = item.get_price() * 0.12
        print(f"Tax [Digital] {item.get_name()}: ${tax}")

    def visit_subscription(self, item):
        tax = item.get_price() * 0.05
        print(f"Tax [Subscription] {item.get_name()}: ${tax}")


class DiscountVisitor(ItemVisitor):
    def __init__(self, percent):
        self.percent = percent

    def visit_physical(self, item):
        discounted = item.get_price() * (1 - self.percent / 100)
        print(f"Discount [Physical] {item.get_name()}: ${item.get_price()} → ${discounted}")

    def visit_digital(self, item):
        discounted = item.get_price() * (1 - self.percent / 100)
        print(f"Discount [Digital] {item.get_name()}: ${item.get_price()} → ${discounted}")

    def visit_subscription(self, item):
        print(f"Discount [Subscription] {item.get_name()}: Subscriptions are not discountable.")


class InvoiceVisitor(ItemVisitor):
    def visit_physical(self, item):
        print(f"INVOICE: {item.get_name()} | Type: Physical | Price: ${item.get_price()} | Ships in 3-5 days")

    def visit_digital(self, item):
        print(f"INVOICE: {item.get_name()} | Type: Digital | Price: ${item.get_price()} | Instant download")

    def visit_subscription(self, item):
        print(f"INVOICE: {item.get_name()} | Type: Subscription | Price: ${item.get_price()}/mo | Activates immediately")


if __name__ == "__main__":
    cart = [
        PhysicalItem("Mechanical Keyboard", 120.00),
        DigitalItem("Photoshop License", 55.00),
        SubscriptionItem("Netflix Plan", 15.00),
    ]

    print("=== Tax Calculation ===")
    tax_visitor = TaxVisitor()
    for item in cart:
        item.accept(tax_visitor)

    print("\n=== Applying 10% Discount ===")
    discount_visitor = DiscountVisitor(10)
    for item in cart:
        item.accept(discount_visitor)

    print("\n=== Generating Invoice ===")
    invoice_visitor = InvoiceVisitor()
    for item in cart:
        item.accept(invoice_visitor)

